package com.zerostreams.app;
import android.content.*;import android.view.*;import android.widget.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import org.json.*;
public class LayoutsTest {
 @Test public void layoutsPersistAndRailCollapsesWhenMovieGetsFocus()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();SharedPreferences prefs=c.getSharedPreferences("zero",0);String before=prefs.getString("uiLayout",null);try{prefs.edit().remove("uiLayout").commit();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(new Intent(c,MainActivity.class).putExtra("downloads",true))){scenario.onActivity(a->Assert.assertEquals(BuildConfig.TV?"classic":"google",a.layoutStyle()));prefs.edit().putString("uiLayout","youtube").commit();scenario.recreate();scenario.onActivity(a->{Assert.assertEquals("youtube",a.layoutStyle());Assert.assertEquals(11,a.layoutRailButtons.size());Button nav=a.layoutRailButtons.keySet().iterator().next();nav.requestFocus();Assert.assertTrue(a.railExpanded);try{View card=a.card(new Catalog.Item(new JSONObject().put("id","fixture-layout").put("title","Layout fixture")),1);java.lang.reflect.Field f=MainActivity.class.getDeclaredField("content");f.setAccessible(true);((LinearLayout)f.get(a)).addView(card);card.requestFocus();Assert.assertFalse("Moving into movies leaves an icon rail",a.railExpanded);Assert.assertEquals("",nav.getText().toString());Assert.assertEquals("Home",nav.getContentDescription().toString());nav.requestFocus();Assert.assertTrue("Returning to rail restores labels",a.railExpanded);}catch(Exception e){throw new RuntimeException(e);}});for(String style:new String[]{"google","classic","youtube"}){prefs.edit().putString("uiLayout",style).commit();scenario.recreate();scenario.onActivity(a->{Assert.assertEquals(style,a.layoutStyle());Assert.assertEquals(style.equals("youtube"),a.layoutRailScroll!=null);a.settings();});}}}finally{if(before==null)prefs.edit().remove("uiLayout").commit();else prefs.edit().putString("uiLayout",before).commit();}}
}
